internal sealed class OkadaDiscriminantRefutationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S0/Certificates/Combinatorics/OkadaDiscriminantRefutation.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Combinatorics/hivert2026okada");
    private static readonly Formula N = F.Id("N"), K = F.Id("K"), X = F.Id("X"), Y = F.Id("Y");
    private static readonly Formula Nat = Seq(Mathbb, Grp(F.Id("N"))), Int = Seq(Mathbb, Grp(F.Id("Z")));
    private static Formula Label => Call("Fin", N);
    private static Formula GenLabel => Call("Fin", Sub(N, D(1)));
    private static Formula Algebra => Call("Presented", N, K, X, Y);
    private static Formula Half => Call("HalfDiagram", N);
    private static Formula Full => Call("Diagram", N);
    private static Formula Fib => Call("FibonacciSet", N);
    private static Formula Arc => Named("Arc");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Hivert--Scott Conjecture 7.9 fails at N = 3 over the rationals with X = (1,2) and Y = (1): the regular-trace determinant is -16 and the cell-determinant product is 1.",
        H("A rank-three refutation of the Okada discriminant identity"),
        Blocks(
            Node("Relations", "Presentation relations", RelationsFormula(),
                "Definition 3.1, page 10: \"Fix a positive integer N. Given a field 𝕂, let X = (x₁, …, x_{N−1}) and Y = (y₁, …, y_{N−2}) be two sequences of element of 𝕂. The Okada algebra O_N(X,Y) is the algebra generated by {E_i | i = 1 … N − 1} and subject to the relations E_i² = x_i E_i (1 ≤ i ≤ N − 1), E_i E_j = E_j E_i (|i − j| ≥ 2), E_{i+1} E_i E_{i+1} = y_i E_{i+1} (1 ≤ i ≤ N − 2).\" Relations is the least inductive binary relation with these three constructors in the free K-algebra. All generator indices are shifted down by one. natSub is natural subtraction truncated at zero; smul is scalar multiplication. Fin.mk inserts the indicated natural value and its bound proof. Qualified proof names display underscore-separated suffixes as nested subscripts.", true),
            Node("Presented", "The presented algebra", General(Eq(Call("Presented", N, K, X, Y), Call("RingQuot", Call("Relations", N, K, X, Y)))),
                "RingQuot takes the algebra quotient imposing the three presentation relations; the carrier is the actual presented algebra, rather than a matrix chosen to stand in for it.", true),
            Node("generator", "Quotient generators", GeneratorFormula(),
                "The generator is the image of the corresponding free-algebra generator under the quotient algebra homomorphism. Paper E_i is generator(i-1).", true),
            Node("code", "Permutation code", CodeFormula(),
                "Definition 3.3, pages 10–11: \"The code of a permutation σ ∈ S_N is the N-tuple code(σ) = (c₁, …, c_N) where c_i := #{k < i | σ⁻¹(k) > σ⁻¹(i)}.\" Finset.card is cardinality, filter retains precisely the elements satisfying its predicate, and symm is the inverse permutation.", true),
            Node("lexmin", "Lexicographically minimal word", LexminFormula(),
                "Page 11: \"It is well known that the product ∏_(i=1)^n s_{i−1}s_{i−2} ··· s_{i−c_i} is the lexicographically minimal reduced factorization of the permutations σ. We denote the associated index word by LexMin(σ).\" finRange lists Fin elements increasingly. Each block is reversed and filtered to the last code(σ,i) entries, then converted to generator indices. flatMap concatenates the blocks in increasing i order.", true),
            Node("lexElement", "Lexmin algebra elements", LexElementFormula(),
                "Definition 3.4, page 11: \"Fix a family of generators (g_i) of a monoid or an algebra. To a permutation σ we associate the element g_σ defined by g_σ := g_LexMin(σ) = ∏_(i=1)^n g_{i−1}g_{i−2} ··· g_{i−c_i}, where (c₁, …, c_N) = code(σ), and the product is increasing with i.\" prod of a list is its ordered product, including the unit for the empty word.", true),
            Node("regularGram", "Regular-trace Gram matrix", RegularFormula(),
                "Page 60: \"Recall the discriminant of the Okada algebra is determinant of the N! × N! matrix G_N with entries given by [G_N]_{σ,τ} := tr [ϱ^reg(E_σ)ϱ^reg(E_τ)] where ϱ^reg is the left-regular representation of O_N(X,Y) and σ, τ ∈ S_N.\" lmul(K,A,z) denotes left multiplication by z on A. trace(K,A,f) is the trace of the linear endomorphism f. The dimension and basis used for this trace are proved at the rational rank-three specialization.", true),
            Node("IsFibonacciSet", "Fibonacci-set predicate", FibonacciPredicate(),
                "Definition 4.5, page 33: \"A Fibonacci set of rank N is a subset S = {s₁ < s₂ < ··· < s_k} of [N] whose size k has the same parity as N and such that s_i has the same parity as i for all i ∈ {1, …, k}.\" mod is natural-number remainder. Counting the members less than s gives its zero-based rank in the increasing enumeration. val of a Fin element extracts its natural label.", true),
            Node("FibonacciSet", "Fibonacci-set carrier", All(N, Nat, Eq(Fib, Subtype(F.Id("S"), Call("Finset", Label), Call("IsFibonacciSet", N, F.Id("S"))))),
                "The subtype carries a finite set together with the Fibonacci-set predicate. Its finite enumeration and decidable equality are the existing subtype instances.", true),
            Node("HalfData", "Incidence data for a half diagram", All(N, Nat, Eq(Call("HalfData", N), PairType(Arrow(Label, Label), Arrow(Label, Label)))),
                "Half-diagram incidence is encoded by a partner map and a label map, both on Fin(N). A fixed partner is a propagating endpoint. Arc and endpoint labels are shifted down by one from the paper.", false),
            Node("HalfValid", "Valid labelled half diagrams", HalfValidFormula(),
                "Definition 3.39, page 23: \"A labelled, non-crossing arc-diagram is called an Okada arc-diagram if the following conditions are satisfied: (1) the label of each arc a — b must be at least 1 and at most min(|a|, |b|), (2) the label of each arc a — b must have the same parity as min(|a|, |b|). (3) if an arc a — b is nested in an arc c — d then the label of a — b is strictly larger than the label of c — d.\" Page 31: \"A half Okada arc-diagram H is a labelled, non-crossing half arc-diagram which satisfies Conditions 1 to 3, or, equivalently, if gluing H with its mirror produces a valid Okada arc-diagram.\" The eight conjuncts encode involutivity, label constancy along an arc, bounds and parity, absence of a propagating point under a nonpropagating arc, noncrossing, and the three nested label orders. fst and snd project incidence data.", true),
            Node("HalfDiagram", "Half-diagram carrier", All(N, Nat, Eq(Half, Subtype(F.Id("H"), Call("HalfData", N), Call("HalfValid", N, F.Id("H"))))),
                "A half diagram consists of its incidence data and the validity predicate. Incidence identifies diagrams up to planar isotopy.", true),
            Node("propagatingIndices", "Propagating endpoints", PropagatingFormula(false),
                "Definition 4.3, page 31: \"The propagating index set of a half Okada arc-diagram H of rank N is the subset PInd(H) of [N] containing the indices of the nodes of its propagating arcs.\" Precisely the fixed points of the partner map propagate.", true),
            Node("propagatingLabels", "Propagating labels", PropagatingFormula(true),
                "Definition 4.3, page 31: \"The propagating label set of a half Okada arc-diagram H of rank N is the subset PLab(H) of [N] containing the labels of its propagating arcs.\" The image of the fixed points under the label map is a finite set, with duplicates removed by Finset.image.", true),
            Node("Diagram", "Full diagrams", DiagramFormula(),
                "Lemma 4.4 (Gluing lemma), page 33, identifies a full diagram with a pair of valid halves having equal propagating label sets. Subtype.val extracts this pair.", true),
            Node("glue", "Gluing halves", GlueFormula(),
                "Gluing lemma, page 33: \"Moreover if L and R are two Okada half arc-diagrams such that PLab(L) = PLab(R), then there is a unique Okada arc-diagram L ⋈ R such that |L ⋈ R⟩ = L and ⟨L ⋈ R| = R.\" glue stores the ordered pair and the equality proof. The formula displays its underlying pair; h is used as the gluing proof argument.", true),
            Node("Arc", "Signed arc data", Eq(Arc, PairType(Int, PairType(Nat, Int))),
                "An arc is a signed left endpoint, a positive paper label, and a signed right endpoint. The tuple is right associated.", false),
            Node("hasArc", "Undirected labelled-arc lookup", HasArcFormula(),
                "hasArc is Boolean lookup in a list of arc triples. beq denotes Boolean equality, band and bor are Boolean conjunction and disjunction, and any is existential Boolean list search. Reversing the endpoints preserves lookup.", false),
            Node("diagramArcs", "Signed arcs of glued halves", ArcsFormula(),
                "The first list records left nonpropagating arcs, the second right nonpropagating arcs with negative endpoints, and the third propagating arcs. For each left propagating endpoint, find searches for the right fixed point with the same label. getD uses that left index if the search fails. This fallback is explicit in the expression; all rank-three arcs used in the refutation are checked. filterMap discards none and retains the value of some.", false),
            Node("flattenWord", "Recursive diagram flattening", FlattenFormula(),
                "Definition 3.55 and Proposition 3.56, pages 27–28, flatten the largest right descent after removing a top identity arc. The formula gives the implemented recursion, including the largest eligible descent d (foldl(max,0)) and the endpoint relabelling. A boolNot predicate removes the selected arc. natAbs is integer absolute value valued in the naturals; castZ is the natural-to-integer cast. Correctness of this recursion for arbitrary rank is not asserted here. Its six rank-three values are checked in the proof.", true),
            Node("diagramElement", "Diagram words in the quotient", DiagramElementFormula(),
                "The flattened positive word is mapped to quotient generators and multiplied in order. An index outside 0 < i < N contributes zero. At rank three every index in the six flattened words is within this interval.", false),
            Node("diagramCoefficient", "Totalized diagram coordinates", CoefficientFormula(),
                "If diagram expansion is bijective, coefficient extraction is evaluation of its inverse linear equivalence. Otherwise it is zero. The symbol h is the proof of bijectivity used in ofBijective; dite binds it in the positive branch. General diagram-basis bijectivity remains unproved in this module. The proof establishes bijectivity at N = 3 over Q with X = (1,2), Y = (1), so the zero branch is unused there.", false),
            Node("CellHalf", "Half diagrams in a cell", CellHalfFormula(),
                "Section 6.1, Restriction and induction of cell modules, equation (35), page 50: \"The left O_N(X,Y) cell module V^S associated to S ∈ 𝕐𝔽𝕊_N can be realized by the vector space spanned by rank N half Okada arc-diagrams |D⟩ such that PLab|D⟩ = S equipped with the left action • obtained by extending linearly the formula E_C • |D⟩ := {λ(C,D) |C · D⟩ if PLab(C · D) = S; 0 otherwise} where D ∈ O_N(X,Y).\" CellHalf is this basis index set; its cardinality supplies dim(Fib(S)) in the conjecture.", true),
            Node("cellAction", "Action on a half-diagram cell", CellActionFormula(),
                "Equation (35), Section 6.1, page 50: the action retains the output half with the prescribed propagating labels. The coordinate at H sums over input halves L, multiplying their vector coefficients by the coefficient of H glued to L in z times the representative of L glued to itself. At rank three, these coefficients are independent of the ket used to represent each input half.", true),
            Node("cellForm", "The cell-form coefficients", CellFormFormula(),
                "Definition 7.7, page 60: \"Let S be a rank N Fibonacci set and let V^S be the associated cell module of O_N(X,Y). Attached to this module is an O_N(X,Y)-invariant bilinear form φ_S: V^S × V^S → 𝕂 implicitly defined for two half diagrams H, K with propagating sets PLab(H) = PLab(K) = S by E_{H ⋈ H} • K = φ_S(H,K) H.\" The definition selects the scalar c satisfying this action equation. Pi.single(H,1) is the half-diagram basis vector; choose(h) selects a scalar from the existence proof h. If no scalar satisfies the equation the value is zero. At rank three the proof establishes existence, the full equation including off-support components, and agreement of this scalar with the diagram coordinate used for the Gram matrices. The solution is unique because its H coordinate is c. General existence and action laws are not proved here.", true),
            Node("cellGram", "Cell Gram matrices", CellGramFormula(),
                "Page 60: \"The Gram matrix G^S_N of the bilinear form φ_S is the dim V^S × dim V^S matrix whose entries are given by [G^S_N]_{H,K} := φ_S(H,K).\" Its index set is exactly CellHalf(N,S).", true),
            Node("claim", "Hivert--Scott Conjecture 7.9", ClaimFormula(),
                "Conjecture 7.9, page 60: \"det G_N = ∏_{S ∈ 𝕐𝔽𝕊_N} [det G^S_N]^{2 dim(Fib(S))}.\" The preamble specifies regular trace, not a normalized trace. The claim quantifies over every positive N, every field in Lean Type, and all parameter sequences. Perm(Fin(N)) indexes the lexmin basis, FibonacciSet(N) indexes the cells, and card(CellHalf(N,S)) encodes dim(Fib(S)). The universal coordinate encoding has the totalization boundary stated above; the specialization that disproves the identity has a checked diagram basis and the source's defining cell-form equation.", true),
            Node("result", "Refutation at rank three", new Formula.Not(F.Id("claim")),
                "At N = 3 over Q with X = (1,2), Y = (1), the quotient words (1,E₁,E₂,E₁E₂,E₂E₁,E₁E₂E₁) form a basis. Span induction proves generation and an explicit map into Q × Q × M₂(Q) proves independence. The regular-trace Gram matrix has rows (6,3,4,2,2,2), (3,3,2,2,2,2), (4,2,8,4,4,2), (2,2,4,2,4,2), (2,2,4,4,2,2), (2,2,2,2,2,2); an exact rational LU factorization gives determinant -16. The three cell Gram matrices are (1), (1), and ((2,1),(1,1)), each with determinant 1. Their dimensions are 1,1,2, so the conjectured product is 1. Thus the exact identity fails. The proof computes both sides from the quotient and gluing definitions.", false, DescribeRole.Theorem)),
        []));

    private static DocumentBlock Node(string declaration, string title, Formula formula, string prose,
        bool literature, DescribeRole role = DescribeRole.Definition, OpenProblemResolutionClaim? resolution = null) =>
        Describe.Lean(DescribeId.Create("okada-" + declaration.ToLowerInvariant()), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.FromAuthor(Disp(formula)),
            literature ? AssessedProvenance.FromLiterature(Source) : AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose))), role, resolution);
    private static Formula Named(string name)
    {
        var tokens = new List<Formula>();
        foreach (var part in name.Split('.'))
        {
            if (tokens.Count > 0) tokens.Add(Dot);
            var words = part.Split('_');
            Formula suffix = F.Id(words[^1]);
            for (int i = words.Length - 2; i >= 0; --i)
                suffix = Seq(F.Id(words[i]), Underscore, Grp(suffix));
            tokens.Add(suffix);
        }
        return Seq(Operatorname, Grp(Seq([.. tokens])));
    }
    private static Formula Call(string name, params Formula[] args) => new Formula.Apply(Named(name), [.. args]);
    private static Formula Apply(Formula f, params Formula[] args) => new Formula.Apply(f, [.. args]);
    private static Formula Parenthesized(Formula x) => Seq(Open, x, Close);
    private static Formula All(Formula v, Formula type, Formula body) => Seq(Forall, Sp, v, Sp, Colon, Sp, type, Comma, Sp, body);
    private static Formula Lam(Formula v, Formula type, Formula body) => Seq(LambdaLower, Sp, v, Sp, Colon, Sp, type, Comma, Sp, body);
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Lt(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThan, b);
    private static Formula Le(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(Parenthesized(a), FormulaLogicOperator.And, Parenthesized(b));
    private static Formula Or(Formula a, Formula b) => new Formula.Logic(Parenthesized(a), FormulaLogicOperator.Or, Parenthesized(b));
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(Parenthesized(a), FormulaLogicOperator.Implies, Parenthesized(b));
    private static Formula Iff(Formula a, Formula b) => new Formula.Logic(Parenthesized(a), FormulaLogicOperator.Iff, Parenthesized(b));
    private static Formula Add(Formula a, Formula b) => new Formula.Binary(a, FormulaBinaryOperator.Add, b);
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(a, FormulaBinaryOperator.Multiply, b);
    private static Formula Sub(Formula a, Formula b) => Call("natSub", a, b);
    private static Formula Mod(Formula a) => Call("mod", a, D(2));
    private static Formula Arrow(Formula a, Formula b) => new Formula.TypeArrow(a, b);
    private static Formula PairType(Formula a, Formula b) => Seq(Parenthesized(a), Sp, Times, Sp, Parenthesized(b));
    private static Formula Pair(Formula a, Formula b) => Parenthesized(Seq(a, Comma, Sp, b));
    private static Formula Val(Formula a) => Call("val", a);
    private static Formula Fst(Formula a) => Call("fst", a);
    private static Formula Snd(Formula a) => Call("snd", a);
    private static Formula Partner(Formula h, Formula i) => Apply(Fst(Val(h)), i);
    private static Formula LabelOf(Formula h, Formula i) => Apply(Snd(Val(h)), i);
    private static Formula Subtype(Formula v, Formula type, Formula p) => Seq(OpenBrace, v, Sp, Colon, Sp, type, Sp, Mid, Sp, p, CloseBrace);
    private static Formula General(Formula body) => All(N, Nat, All(K, Named("Type"),
        Seq(OpenBracket, Call("Field", K), CloseBracket, Sp, All(X, Arrow(GenLabel, K), All(Y, Arrow(Call("Fin", Sub(N, D(2))), K), body)))));
    private static Formula ListOf(Formula type) => Call("List", type);
    private static Formula Empty => Seq(OpenBracket, CloseBracket);
    private static Formula Glue(Formula h, Formula k, Formula proof) => Call("glue", N, h, k, proof);
    private static Formula GlueSelf(Formula h) => Glue(h, h, Call("rfl", Call("propagatingLabels", N, h)));
    private static Formula GlueProof(Formula h, Formula k) => Call("trans", Call("prop", h), Call("symm", Call("prop", k)));
    private static Formula Element(Formula d) => Call("diagramElement", N, K, X, Y, d);
    private static Formula Coefficient(Formula d, Formula z) => Call("diagramCoefficient", N, K, X, Y, d, z);

    private static Formula RelationsFormula()
    {
        Formula i = F.Id("i"), j = F.Id("j"), h = F.Id("h");
        Formula G(Formula t) => Call("iota", K, t);
        Formula R(Formula a, Formula b) => Call("Relations", N, K, X, Y, a, b);
        Formula square = All(i, GenLabel, R(Mul(G(i), G(i)), Call("smul", Apply(X, i), G(i))));
        Formula commute = All(i, GenLabel, All(j, GenLabel, Imp(Or(Le(Add(Val(i), D(2)), Val(j)), Le(Add(Val(j), D(2)), Val(i))), R(Mul(G(i), G(j)), Mul(G(j), G(i))))));
        Formula next = Call("Fin.mk", Add(Val(i), D(1)), h);
        Formula previous = Call("Fin.mk", Val(i), Call("Nat.lt_of_succ_lt", h));
        Formula sandwich = All(i, Call("Fin", Sub(N, D(2))), All(h, Lt(Add(Val(i), D(1)), Sub(N, D(1))),
            R(Mul(Mul(G(next), G(previous)), G(next)), Call("smul", Apply(Y, i), G(next)))));
        return General(And(square, And(commute, sandwich)));
    }
    private static Formula GeneratorFormula()
    {
        Formula i = F.Id("i");
        return General(All(i, GenLabel, Eq(Call("generator", N, K, X, Y, i), Apply(Call("mkAlgHom", K, Call("Relations", N, K, X, Y)), Call("iota", K, i)))));
    }
    private static Formula CodeFormula()
    {
        Formula p = F.Id("sigma"), i = F.Id("i"), k = F.Id("k");
        Formula filtered = Call("filter", Parenthesized(Lam(k, Label, And(Lt(k, i), Lt(Apply(Call("symm", p), i), Apply(Call("symm", p), k))))), Call("univ", Label));
        return All(N, Nat, All(p, Call("Perm", Label), All(i, Label, Eq(Call("code", N, p, i), Call("card", filtered)))));
    }
    private static Formula LexminFormula()
    {
        Formula p = F.Id("sigma"), i = F.Id("i"), j = F.Id("j");
        Formula js = Call("filter", Parenthesized(Lam(j, Call("Fin", Val(i)), Le(Sub(Val(i), Call("code", N, p, i)), Val(j)))), Call("reverse", Call("finRange", Val(i))));
        Formula block = Call("map", Parenthesized(Lam(j, Call("Fin", Val(i)), Call("Fin.mk", Val(j), Call("Nat.lt_of_lt_of_le", Call("Fin.isLt", j), Call("Nat.le_sub_one_of_lt", Call("Fin.isLt", i)))))), js);
        return All(N, Nat, All(p, Call("Perm", Label), Eq(Call("lexmin", N, p), Call("flatMap", Parenthesized(Lam(i, Label, block)), Call("finRange", N)))));
    }
    private static Formula LexElementFormula()
    {
        Formula p = F.Id("sigma");
        return General(All(p, Call("Perm", Label), Eq(Call("lexElement", N, K, X, Y, p), Call("prod", Call("map", Call("generator", N, K, X, Y), Call("lexmin", N, p))))));
    }
    private static Formula RegularFormula()
    {
        Formula p = F.Id("sigma"), q = F.Id("tau");
        Formula L(Formula r) => Call("lmul", K, Algebra, Call("lexElement", N, K, X, Y, r));
        return General(All(p, Call("Perm", Label), All(q, Call("Perm", Label), Eq(Apply(Call("regularGram", N, K, X, Y), p, q), Call("trace", K, Algebra, Mul(L(p), L(q)))))));
    }
    private static Formula FibonacciPredicate()
    {
        Formula s = F.Id("S"), x = F.Id("s"), t = F.Id("t");
        Formula rank = Call("card", Call("filter", Parenthesized(Lam(t, Label, Lt(t, x))), s));
        Formula p = And(Eq(Mod(Call("card", s)), Mod(N)), All(x, Label, Imp(new Formula.Relation(x, FormulaRelationOperator.MemberOf, s), Eq(Mod(Add(Val(x), D(1))), Mod(Add(rank, D(1)))))));
        return All(N, Nat, All(s, Call("Finset", Label), Iff(Call("IsFibonacciSet", N, s), p)));
    }
    private static Formula HalfValidFormula()
    {
        Formula h = F.Id("H"), i = F.Id("i"), j = F.Id("j");
        Formula P(Formula x) => Apply(Fst(h), x);
        Formula L(Formula x) => Apply(Snd(h), x);
        Formula A(Formula x) => Lt(x, P(x));
        Formula Two(Formula body) => All(i, Label, All(j, Label, body));
        Formula[] c = [All(i, Label, Eq(P(P(i)), i)), All(i, Label, Eq(L(P(i)), L(i))),
            All(i, Label, And(Le(L(i), i), Eq(Mod(Val(L(i))), Mod(Val(Call("min", i, P(i))))))),
            Two(Imp(A(i), Imp(Eq(P(j), j), new Formula.Not(Parenthesized(And(Lt(i,j), Lt(j,P(i)))))))),
            Two(Imp(A(i), Imp(A(j), Imp(Lt(i,j), Imp(Lt(j,P(i)), Lt(P(j),P(i))))))),
            Two(Imp(A(i), Imp(A(j), Imp(Lt(i,j), Imp(Lt(P(j),P(i)), Lt(L(i),L(j))))))),
            Two(Imp(Eq(P(i),i), Imp(A(j), Imp(Lt(i,j), Lt(L(i),L(j)))))),
            Two(Imp(Eq(P(i),i), Imp(Eq(P(j),j), Imp(Lt(i,j), Lt(L(i),L(j))))))];
        Formula conditions = c[^1];
        for (int k = c.Length - 2; k >= 0; --k) conditions = And(c[k], conditions);
        return All(N, Nat, All(h, Call("HalfData", N), Iff(Call("HalfValid", N, h), conditions)));
    }
    private static Formula PropagatingFormula(bool labels)
    {
        Formula h = F.Id("H"), i = F.Id("i");
        Formula indices = Call("filter", Parenthesized(Lam(i, Label, Eq(Partner(h,i),i))), Call("univ", Label));
        Formula body = labels ? Call("image", Snd(Val(h)), Call("propagatingIndices", N, h)) : indices;
        return All(N, Nat, All(h, Half, Eq(Call(labels ? "propagatingLabels" : "propagatingIndices", N, h), body)));
    }
    private static Formula DiagramFormula()
    {
        Formula hk = F.Id("HK");
        return All(N, Nat, Eq(Full, Subtype(hk, PairType(Half, Half), Eq(Call("propagatingLabels", N, Fst(hk)), Call("propagatingLabels", N, Snd(hk))))));
    }
    private static Formula GlueFormula()
    {
        Formula h = F.Id("H"), k = F.Id("L"), p = F.Id("h");
        return All(N, Nat, All(h, Half, All(k, Half, All(p, Eq(Call("propagatingLabels", N, h), Call("propagatingLabels", N, k)), Eq(Val(Glue(h,k,p)), Pair(h,k))))));
    }
    private static Formula HasArcFormula()
    {
        Formula arcs = F.Id("arcs"), i = F.Id("i"), j = F.Id("j"), label = F.Id("label"), a = F.Id("a");
        Formula Same(Formula x, Formula y) => Call("beq",x,y);
        Formula ends = Call("bor", Call("band", Same(Fst(a),i), Same(Snd(Snd(a)),j)), Call("band", Same(Fst(a),j), Same(Snd(Snd(a)),i)));
        return All(arcs, ListOf(Arc), All(i, Int, All(label, Nat, All(j, Int, Eq(Call("hasArc",arcs,i,label,j), Call("any", Parenthesized(Lam(a,Arc,Call("band",Same(Fst(Snd(a)),label),ends))),arcs))))));
    }
    private static Formula ArcsFormula()
    {
        Formula d = F.Id("D"), i = F.Id("i"), j = F.Id("j"), h = Fst(Val(d)), k = Snd(Val(d));
